PROGRAM PRG_UnityRVM
VAR
    control : FB_RVMControl106;
    candidate : ST_RVMInput106;
    snapshot : ST_RVMInput106;
    op : ST_RVMOperator106;
    initialized : BOOL;
    epoch : UDINT;
    beginMarker : UDINT;
    lastMarker : UDINT;
    outputMarker : UDINT;
    fresh : BOOL;
END_VAR

ST.xhtml:
IF NOT initialized THEN
    initialized := TRUE;
    IF GVL_RVMKalici.udiOturum < UDINT#4294967295 THEN
        GVL_RVMKalici.udiOturum := GVL_RVMKalici.udiOturum + 1;
        epoch := GVL_RVMKalici.udiOturum;
    END_IF;
END_IF;
fresh := FALSE;
beginMarker := GVL_RVMUnity.udiGirisBaslangic;
IF (beginMarker <> 0) AND (beginMarker = GVL_RVMUnity.udiGirisBitis) AND (beginMarker <> lastMarker) THEN
candidate.uiUnityProtokol := GVL_RVMUnity.uiUnityProtokol;
candidate.udiUnityOturumu := GVL_RVMUnity.udiUnityOturumu;
candidate.udiUnitySayaci := GVL_RVMUnity.udiUnitySayaci;
candidate.udiKomutKimligi := GVL_RVMUnity.udiKomutKimligi;
