candidate.xAcilStop := GVL_RVMUnity.xAcilStop;
candidate.xKutuPetDolu := GVL_RVMUnity.xKutuPetDolu;
candidate.xKutuAluminyumDolu := GVL_RVMUnity.xKutuAluminyumDolu;
candidate.xKutuCamDolu := GVL_RVMUnity.xKutuCamDolu;
candidate.rKutleGram := GVL_RVMUnity.rKutleGram;
candidate.rOptikGecirgenlik := GVL_RVMUnity.rOptikGecirgenlik;
candidate.rBoyMetre := GVL_RVMUnity.rBoyMetre;
candidate.rHazneKonumu := GVL_RVMUnity.rHazneKonumu;
candidate.rGercekBantHizi := GVL_RVMUnity.rGercekBantHizi;
candidate.rGercekKiriciDevri := GVL_RVMUnity.rGercekKiriciDevri;
candidate.uiBosaltilanKutu := GVL_RVMUnity.uiBosaltilanKutu;
candidate.udiUrunKimligi := GVL_RVMUnity.udiUrunKimligi;
candidate.uiOperatorParametresi := GVL_RVMUnity.uiOperatorParametresi;
candidate.udiGorulenPlcOturumu := GVL_RVMUnity.udiGorulenPlcOturumu;
candidate.udiNesneOnayi := GVL_RVMUnity.udiNesneOnayi;
candidate.uiNesneSonucu := GVL_RVMUnity.uiNesneSonucu;
candidate.udiNesneUrunKimligi := GVL_RVMUnity.udiNesneUrunKimligi;
candidate.uiPlantVeriKaynagi := GVL_RVMUnity.uiPlantVeriKaynagi;
candidate.xPlantVerisiGecerli := GVL_RVMUnity.xPlantVerisiGecerli;
candidate.udiGoruntuOnayi := GVL_RVMUnity.udiGoruntuOnayi;
candidate.udiGoruntuUrunu := GVL_RVMUnity.udiGoruntuUrunu;
candidate.udiGoruntuPlcOturumu := GVL_RVMUnity.udiGoruntuPlcOturumu;
candidate.udiGoruntuUnityOturumu := GVL_RVMUnity.udiGoruntuUnityOturumu;
candidate.xGoruntuGecerli := GVL_RVMUnity.xGoruntuGecerli;
candidate.xGoruntuNesneVar := GVL_RVMUnity.xGoruntuNesneVar;
candidate.rGoruntuBoy := GVL_RVMUnity.rGoruntuBoy;
candidate.rGoruntuEn := GVL_RVMUnity.rGoruntuEn;
candidate.rGoruntuDoluluk := GVL_RVMUnity.rGoruntuDoluluk;
candidate.rGoruntuYasiMs := GVL_RVMUnity.rGoruntuYasiMs;
candidate.xOlcumTartiGecerli := GVL_RVMUnity.xOlcumTartiGecerli;
candidate.xOlcumProbGecerli := GVL_RVMUnity.xOlcumProbGecerli;
candidate.rOlcumYansima := GVL_RVMUnity.rOlcumYansima;
candidate.rOlcumMetal := GVL_RVMUnity.rOlcumMetal;
candidate.rOlcumManyetik := GVL_RVMUnity.rOlcumManyetik;
    fresh := (beginMarker = GVL_RVMUnity.udiGirisBitis) AND (beginMarker = GVL_RVMUnity.udiGirisBaslangic);
    IF fresh THEN snapshot := candidate; lastMarker := beginMarker; END_IF;
END_IF;
op.xBaslat := GVL_RVMOperator.xBaslat;
op.xDurdur := GVL_RVMOperator.xDurdur;
op.xSifirla := GVL_RVMOperator.xSifirla;
op.xNesneEkle := GVL_RVMOperator.xNesneEkle;
op.xModUygula := GVL_RVMOperator.xModUygula;
op.xAcilStop := GVL_RVMOperator.xAcilStop;
op.uiSeciliNesne := GVL_RVMOperator.uiSeciliNesne;
op.uiSeciliMod := GVL_RVMOperator.uiSeciliMod;
control(inp := snapshot, op := op, fresh := fresh, epoch := epoch);
IF outputMarker = UDINT#4294967295 THEN outputMarker := 1; ELSE outputMarker := outputMarker+1; END_IF;
GVL_RVMUnity.udiCikisBaslangic := outputMarker;
GVL_RVMUnity.uiProtokolSurumu := control.q.uiProtokolSurumu;
GVL_RVMUnity.udiPlcSayaci := control.q.udiPlcSayaci;
